mapper.select:
SELECT slot, speed, mode, updated_at
FROM fan_board
WHERE slot = #{slot}

mapper.update:
UPDATE fan_board
SET speed = #{speed}, updated_at = #{updatedAt}
WHERE slot = #{slot}

UPDATE fan_board
SET speed = #{speed}, updated_at = #{updatedAt}
WHERE slot = #{slot} AND mode = 'AUTOMATIC'

UPDATE fan_board
SET mode = #{mode}, updated_at = #{updatedAt}
WHERE slot = #{slot}
